script <- sub('^--file=','',grep('^--file=',commandArgs(FALSE),value=TRUE))
root <- dirname(dirname(normalizePath(script)));out <- file.path(root,'output')
d <- read.csv(file.path(out,'world_trade_annual_GHG_IMP_VAL_old_source.csv'))
stopifnot(nrow(d)==17*75,!anyDuplicated(d[c('region','year')]),all(is.finite(d$net_payment_million_model_USD_per_year)))
report <- d[d$year%%5==0,]
payment_error <- max(abs(report$net_payment_million_model_USD_per_year-report$processed_GHG_IMP_VAL))
quantity_error <- max(abs(report$net_import_MtCO2eq_per_year-report$processed_GHG_IMP_thousand_tonnes/1000))
stopifnot(payment_error<1e-5,quantity_error<1e-7)
years <- sort(unique(d$year))
audit <- do.call(rbind,lapply(years,function(y){z <- d[d$year==y,];p <- z$net_payment_million_model_USD_per_year/1000;q <- z$net_import_MtCO2eq_per_year/1000
 data.frame(year=y,buy_quantity_Gt=sum(pmax(q,0)),sell_quantity_Gt=sum(pmax(-q,0)),buy_value_billion_model_USD=sum(pmax(p,0)),sell_value_billion_model_USD=sum(pmax(-p,0)))
}))
stopifnot(max(abs(audit$buy_quantity_Gt-audit$sell_quantity_Gt))<1e-7,max(abs(audit$buy_value_billion_model_USD-audit$sell_value_billion_model_USD))<1e-6)
result <- data.frame(year=years,trade_volume_GtCO2eq_per_year=audit$buy_quantity_Gt,trade_value_billion_model_USD_per_year=audit$buy_value_billion_model_USD)
write.csv(result,file.path(out,'world_allowance_volume_value_annual_old.csv'),row.names=FALSE)
write.csv(audit,file.path(out,'world_allowance_volume_value_annual_old_audit.csv'),row.names=FALSE)
q <- result$trade_volume_GtCO2eq_per_year*1000;money <- result$trade_value_billion_model_USD_per_year
# Reuse the established figure styling; the data above are annual model observations.
template <- paste(readLines(file.path(root,'prog/plot_world_allowance_volume_value_IAMC_old.R')),collapse='\n')
plotcode <- substring(template,regexpr('draw <- function()',template,fixed=TRUE)[1])
plotcode <- gsub('IAMC World series','GHG_IMP_VAL-equivalent annual transaction values',plotcode,fixed=TRUE)
plotcode <- gsub('billion 2010 USD / year','billion 2005 USD / year',plotcode,fixed=TRUE)
plotcode <- gsub(';points(years,q/1000,col=\"#1457ED\",pch=19,cex=.7)','',plotcode,fixed=TRUE)
plotcode <- gsub(';points(years,money,col=\"#F04416\",pch=17,cex=.7)','',plotcode,fixed=TRUE)
plotcode <- gsub(',pch=c(19,17)','',plotcode,fixed=TRUE)
plotcode <- gsub('points(years,q/1000,col=\"#1457ED\",pch=19,cex=.7)','invisible(NULL)',plotcode,fixed=TRUE)
plotcode <- gsub('points(years,money,col=\"#F04416\",pch=17,cex=.7)','invisible(NULL)',plotcode,fixed=TRUE)
plotcode <- gsub("points(years,q/1000,col='#1457ED',pch=19,cex=.7)",'invisible(NULL)',plotcode,fixed=TRUE)
plotcode <- gsub("points(years,money,col='#F04416',pch=17,cex=.7)",'invisible(NULL)',plotcode,fixed=TRUE)
plotcode <- gsub('at=c(2026,2030,2040,2050,2060,2075,2090,2100)','at=c(2026,2050,2075,2100),labels=c("2026","","2075","2100")',plotcode,fixed=TRUE)
plotcode <- gsub("axis(2,col.axis='#1457ED')","axis(1,at=2050,labels='2050',font=2,lwd.ticks=2);axis(2,col.axis='#1457ED')",plotcode,fixed=TRUE)
plotcode <- gsub("lines(years,money,col='#F04416',lwd=2.3,lty=2)","lines(years,money,col='#F04416',lwd=2.3,lty=1)",plotcode,fixed=TRUE)
plotcode <- gsub('lty=c(1,2)','lty=c(1,1)',plotcode,fixed=TRUE)
plotcode <- gsub("axis(2,col.axis='#1457ED')","axis(2,col.axis='black')",plotcode,fixed=TRUE)
plotcode <- gsub("axis(4,col.axis='#F04416')","axis(4,col.axis='black')",plotcode,fixed=TRUE)
plotcode <- gsub("las=0,col='#1457ED'","las=0,col='black'",plotcode,fixed=TRUE)
plotcode <- gsub("las=0,col='#F04416'","las=0,col='black'",plotcode,fixed=TRUE)
plotcode <- gsub("fig=c(0,1,0,.12)","fig=c(0,1,0,.085)",plotcode,fixed=TRUE)
plotcode <- gsub("legend('top',","legend('top',inset=c(0,.03),",plotcode,fixed=TRUE)
plotcode <- gsub('Source: IAMC World Trd_Emi_All_Vol and Trd_Emi_All_Val. Markers: five-year observations; lines connect observations.','Annual raw PSAM_value(ROW, GHGC), checked against GHG_IMP_VAL. Buyers and sellers balance; no interpolation.',plotcode,fixed=TRUE)
plotcode <- gsub('world_allowance_volume_value_IAMC_old','world_allowance_volume_value_annual_old',plotcode,fixed=TRUE)
# Keep the title; omit only the upper subtitle for the presentation figure.
plotlines <- strsplit(plotcode,'\n',fixed=TRUE)[[1]]
plotlines <- plotlines[!grepl("mtext('Global emissions allowance trade:|mtext('NZE_w/ET |",plotlines,fixed=TRUE)]
plotlines <- plotlines[!grepl('NZE_w/ET \\| Previous model results',plotlines)]
plotcode <- paste(plotlines,collapse='\n')
eval(parse(text=plotcode))
writeLines(c(paste('Maximum GHG_IMP_VAL comparison error (million 2005 USD/year):',payment_error),paste('Maximum quantity comparison error (Mt/year):',quantity_error),'Currency: base-year-2005 USD transaction values, not rebased to 2010. This is not a separate constant-price quantity valuation.','Evidence: combine_gdx1.gms base_year=2005; GHG_IMP_VAL=PSAM_value(ROW,GHGC). IAMC iiasa_database_ind.gms separately rebases economic indicators from 2005 to 2010 at lines 1424-1439.','Historical identity of the local source-code version with the executable used for these old results is not independently established.'),file.path(out,'world_allowance_volume_value_annual_old_validation.txt'))
cat('Payment comparison error:',payment_error,'; max world monetary imbalance:',max(abs(audit$buy_value_billion_model_USD-audit$sell_value_billion_model_USD)),'\n')
